-- VFDA VA Quiz App - Phase 1 database (tables + row-level security).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run once on an empty project.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261029130000_master_content.sql =====

-- Master content: the same for every office, loaded from seed/quiz-bank.json.

-- Helpers live in a schema the Supabase API does not expose.
create schema if not exists private;

create or replace function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- One interview question, e.g. EHR_PATH_SEARCH.
create table public.interview_questions (
  id          uuid primary key default gen_random_uuid(),
  key         text not null unique,
  quiz        text not null,                    -- 'PROFILE' or a quiz code like 'W1D1'
  question    text not null,
  answer_type text not null check (answer_type in
                ('text', 'list', 'yesno', 'upload', 'matrix', 'click_path', 'choice')),
  condition   text not null default 'always',   -- a key of settings.conditions
  source      text not null default '',
  position    integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- One of the 10 quizzes (W1D1 ... W2D5).
create table public.quiz_templates (
  id                uuid primary key default gen_random_uuid(),
  code              text not null unique,
  week              smallint not null check (week between 1 and 2),
  day               smallint not null check (day between 1 and 5),
  title             text not null,
  cards             text[] not null default '{}',
  condition         text not null default 'always',
  max_points        integer not null check (max_points > 0),
  pass_points       integer not null,
  review_min_points integer not null,
  answer_format     text not null check (answer_format in ('steps_say_doc', 'say_do_book')),
  proof_of_work     text[] not null default '{}',
  notes             text not null default '',
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (week, day),
  check (review_min_points <= pass_points and pass_points <= max_points)
);

-- One quiz item, version A or B. Holds answer keys: never readable by VAs.
create table public.question_templates (
  id               uuid primary key default gen_random_uuid(),
  quiz_template_id uuid not null references public.quiz_templates (id) on delete cascade,
  part             text not null,                -- 'A', 'B', 'B-alt', ...
  part_title       text not null default '',
  condition        text not null default 'always',
  code             text not null,                -- 'A1', 'B3', ...
  version          text not null default 'A' check (version in ('A', 'B')),
  type             text not null check (type in ('mc', 'situational')),
  stem             text not null,
  options          jsonb,                        -- fixed options for mc items
  options_rule     text,                         -- or a rule for building them per office
  answer           text,                         -- mc answer
  look_for         jsonb,                        -- situational grading points
  critical_fail    text,
  bank_ref         text not null default '',
  points           smallint not null check (points in (1, 2)),
  answer_format    text check (answer_format in ('steps_say_doc', 'say_do_book')),
  position         integer not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (quiz_template_id, code, version)
);
create index on public.question_templates (quiz_template_id);

-- JSON settings from the Quiz Bank: conditions, grading, sequence, gray_* ...
create table public.settings (
  key        text primary key,
  value      jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger set_updated_at before update on public.interview_questions
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.quiz_templates
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.question_templates
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.settings
  for each row execute function private.set_updated_at();

-- ===== 20261029130100_offices_and_people.sql =====

-- Office data (per clinic, from the interview) and people (logins).

-- One office. Profile answers are copied here from the interview because they
-- decide which quizzes and parts the office gets.
create table public.clinics (
  id                 uuid primary key default gen_random_uuid(),
  name               text not null,
  status             text not null default 'interview' check (status in
                       ('interview', 'quizzes_in_review', 'va_training', 'done')),
  bills_insurance    boolean,
  billing_type       text check (billing_type in ('insurance', 'cash', 'both', 'none')),
  has_reexam_card    boolean,
  has_gray_cards     boolean,
  remote_access_tool text,                      -- null = not answered, 'none' = no remote access
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

-- One login. Created automatically when someone first signs in, with no role:
-- they see nothing until VFDA (or supabase/seed.sql) gives them one.
create table public.profiles (
  id                  uuid primary key references auth.users (id) on delete cascade,
  email               text not null,
  full_name           text not null default '',
  role                text check (role in ('vfda_admin', 'doctor', 'va')),
  clinic_id           uuid references public.clinics (id) on delete set null,
  training_start_date date,                     -- VAs only: day 1 of their training
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  -- doctors and VAs always belong to a clinic
  check (role is null or role = 'vfda_admin' or clinic_id is not null)
);
create index on public.profiles (clinic_id);
create index on public.profiles (lower(email));

create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email)
  values (new.id, coalesce(new.email, ''))
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

-- One interview answer for one office.
create table public.interview_answers (
  id           uuid primary key default gen_random_uuid(),
  clinic_id    uuid not null references public.clinics (id) on delete cascade,
  question_key text not null references public.interview_questions (key) on update cascade,
  value        jsonb,
  attachments  jsonb not null default '[]',     -- storage paths or Loom links
  answered_by  uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (clinic_id, question_key)
);

-- One extra office-specific task (gray card).
create table public.gray_cards (
  id         uuid primary key default gen_random_uuid(),
  clinic_id  uuid not null references public.clinics (id) on delete cascade,
  answers    jsonb not null default '{}',       -- CARD_NAME, CARD_TRIGGER, ... from settings.gray_card_questions
  risk_tag   text check (risk_tag in ('high_risk', 'frequent', 'occasional')),
  frequency  text,
  position   integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.gray_cards (clinic_id);

-- One quiz built for one office. Version A and version B are separate rows.
create table public.clinic_quizzes (
  id               uuid primary key default gen_random_uuid(),
  clinic_id        uuid not null references public.clinics (id) on delete cascade,
  quiz_template_id uuid not null references public.quiz_templates (id) on delete restrict,
  version          text not null default 'A' check (version in ('A', 'B')),
  status           text not null default 'draft' check (status in ('draft', 'in_review', 'approved')),
  approved_by      uuid references public.profiles (id) on delete set null,
  approved_at      timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (clinic_id, quiz_template_id, version)
);
create index on public.clinic_quizzes (quiz_template_id);

-- One filled-in item. Holds answer keys: never readable by VAs (see get_open_quiz_items).
-- Display fields are copied in so gray-card items, which have no master item, work the same way.
create table public.clinic_questions (
  id                   uuid primary key default gen_random_uuid(),
  clinic_quiz_id       uuid not null references public.clinic_quizzes (id) on delete cascade,
  question_template_id uuid references public.question_templates (id) on delete set null,
  gray_card_id         uuid references public.gray_cards (id) on delete set null,
  position             integer not null default 0,
  part                 text not null,
  part_title           text not null default '',
  code                 text not null,
  type                 text not null check (type in ('mc', 'situational')),
  points               smallint not null check (points in (1, 2)),
  answer_format        text check (answer_format in ('steps_say_doc', 'say_do_book')),
  stem                 text not null,
  options              jsonb,
  answer               text,
  look_for             jsonb,
  critical_fail        text,
  edited_by_vfda       boolean not null default false,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (clinic_quiz_id, code)
);

create trigger set_updated_at before update on public.clinics
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.profiles
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.interview_answers
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.gray_cards
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.clinic_quizzes
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.clinic_questions
  for each row execute function private.set_updated_at();

-- ===== 20261029130200_va_progress.sql =====

-- VA progress: unlocks, attempts, proof of work, and sent reports.

-- One VA's status on one quiz (one version of it).
create table public.unlocks (
  id             uuid primary key default gen_random_uuid(),
  va_id          uuid not null references public.profiles (id) on delete cascade,
  clinic_quiz_id uuid not null references public.clinic_quizzes (id) on delete cascade,
  status         text not null default 'locked' check (status in
                   ('locked', 'open', 'submitted', 'passed', 'in_review', 'retake')),
  cards_done_at  timestamptz,
  unlocked_at    timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (va_id, clinic_quiz_id)
);
create index on public.unlocks (clinic_quiz_id);

-- One quiz attempt. The unique key enforces one attempt per version.
create table public.attempts (
  id                   uuid primary key default gen_random_uuid(),
  va_id                uuid not null references public.profiles (id) on delete cascade,
  clinic_quiz_id       uuid not null references public.clinic_quizzes (id) on delete cascade,
  version              text not null check (version in ('A', 'B')),
  started_at           timestamptz not null default now(),
  submitted_at         timestamptz,
  answers              jsonb not null default '{}',   -- keyed by clinic_questions.id
  item_times           jsonb not null default '{}',   -- seconds spent per item
  paste_log            jsonb not null default '[]',   -- logged, never blocked
  score                numeric(6, 2),
  result               text check (result in ('pass', 'review', 'retake')),
  critical_errors      jsonb not null default '[]',
  ai_evaluation        jsonb,
  vfda_override        jsonb,                          -- {score, note, by, at}
  feedback_released_at timestamptz,                    -- VA sees the attempt only after this is set
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (va_id, clinic_quiz_id)
);
create index on public.attempts (clinic_quiz_id);

-- One proof-of-work file or Loom link.
create table public.proof_uploads (
  id             uuid primary key default gen_random_uuid(),
  va_id          uuid not null references public.profiles (id) on delete cascade,
  clinic_quiz_id uuid not null references public.clinic_quizzes (id) on delete cascade,
  file_path      text,                                 -- path in Supabase Storage
  link_url       text,
  status         text not null default 'pending' check (status in ('pending', 'accepted', 'redo')),
  review_note    text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check (file_path is not null or link_url is not null)
);
create index on public.proof_uploads (va_id);
create index on public.proof_uploads (clinic_quiz_id);

-- One report sent about an attempt.
create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  attempt_id uuid not null references public.attempts (id) on delete cascade,
  channel    text not null check (channel in ('email', 'slack')),
  recipient  text not null,
  sent_at    timestamptz,
  error      text,
  created_at timestamptz not null default now()
);
create index on public.notifications (attempt_id);

create trigger set_updated_at before update on public.unlocks
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.attempts
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.proof_uploads
  for each row execute function private.set_updated_at();

-- ===== 20261029130300_row_level_security.sql =====

-- Row-level security on every table.
--   vfda_admin: everything.
--   doctor:     only their own clinic's rows (and their VAs' results).
--   va:         only their own unlocks, released attempts and proof uploads;
--               quiz items only through get_open_quiz_items(), never answer keys.
--   no role:    nothing but their own profile.
-- The service-role key (server only) bypasses all of this for grading and reports.

-- ---------------------------------------------------------------------------
-- Helpers. SECURITY DEFINER so policies can look up the caller's profile
-- without recursing into profiles' own policies. Not exposed by the API.
-- ---------------------------------------------------------------------------

create or replace function private.my_role()
returns text
language sql stable security definer
set search_path = ''
as $$
  select role from public.profiles where id = (select auth.uid());
$$;

create or replace function private.my_clinic_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$
  select clinic_id from public.profiles where id = (select auth.uid());
$$;

create or replace function private.is_admin()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(private.my_role() = 'vfda_admin', false);
$$;

-- True when the caller is the doctor of this clinic.
create or replace function private.is_doctor_of_clinic(p_clinic_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(private.my_role() = 'doctor' and private.my_clinic_id() = p_clinic_id, false);
$$;

-- True when the caller is the doctor of the clinic this quiz was built for.
create or replace function private.is_doctor_of_clinic_quiz(p_clinic_quiz_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.clinic_quizzes q
    where q.id = p_clinic_quiz_id
      and private.is_doctor_of_clinic(q.clinic_id)
  );
$$;

-- True when the caller is a VA with an unlock row for this quiz (any status).
create or replace function private.va_has_unlock(p_clinic_quiz_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select private.my_role() = 'va' and exists (
    select 1 from public.unlocks u
    where u.clinic_quiz_id = p_clinic_quiz_id
      and u.va_id = (select auth.uid())
  );
$$;

grant usage on schema private to authenticated;
grant execute on all functions in schema private to authenticated;

-- ---------------------------------------------------------------------------
-- Turn RLS on everywhere. Logged-out visitors (anon) get no table access at all.
-- ---------------------------------------------------------------------------

alter table public.interview_questions enable row level security;
alter table public.quiz_templates      enable row level security;
alter table public.question_templates  enable row level security;
alter table public.settings            enable row level security;
alter table public.clinics             enable row level security;
alter table public.profiles            enable row level security;
alter table public.interview_answers   enable row level security;
alter table public.gray_cards          enable row level security;
alter table public.clinic_quizzes      enable row level security;
alter table public.clinic_questions    enable row level security;
alter table public.unlocks             enable row level security;
alter table public.attempts            enable row level security;
alter table public.proof_uploads       enable row level security;
alter table public.notifications       enable row level security;

revoke all on
  public.interview_questions, public.quiz_templates, public.question_templates,
  public.settings, public.clinics, public.profiles, public.interview_answers,
  public.gray_cards, public.clinic_quizzes, public.clinic_questions,
  public.unlocks, public.attempts, public.proof_uploads, public.notifications
from anon;

-- ---------------------------------------------------------------------------
-- vfda_admin: full access to every table.
-- ---------------------------------------------------------------------------

create policy "admin full access" on public.interview_questions for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.quiz_templates for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.question_templates for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.settings for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.clinics for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.profiles for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.interview_answers for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.gray_cards for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.clinic_quizzes for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.clinic_questions for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.unlocks for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.attempts for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.proof_uploads for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "admin full access" on public.notifications for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));

-- ---------------------------------------------------------------------------
-- Everyone signed in: their own profile (read only; only VFDA changes roles).
-- ---------------------------------------------------------------------------

create policy "read own profile" on public.profiles for select to authenticated
  using (id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Master content. question_templates and settings stay admin-only.
-- ---------------------------------------------------------------------------

create policy "doctor reads interview questions" on public.interview_questions
  for select to authenticated
  using ((select private.my_role()) = 'doctor');

-- Quiz titles, cards and points; no answer keys live in this table.
create policy "doctor and va read quiz templates" on public.quiz_templates
  for select to authenticated
  using ((select private.my_role()) in ('doctor', 'va'));

-- ---------------------------------------------------------------------------
-- Doctor: own clinic only.
-- ---------------------------------------------------------------------------

create policy "doctor and va read own clinic" on public.clinics
  for select to authenticated
  using (id = (select private.my_clinic_id()) and (select private.my_role()) in ('doctor', 'va'));

create policy "doctor reads own clinic profiles" on public.profiles
  for select to authenticated
  using (private.is_doctor_of_clinic(clinic_id));

create policy "doctor reads own interview" on public.interview_answers
  for select to authenticated
  using (private.is_doctor_of_clinic(clinic_id));
create policy "doctor adds own interview answers" on public.interview_answers
  for insert to authenticated
  with check (private.is_doctor_of_clinic(clinic_id) and answered_by = (select auth.uid()));
create policy "doctor edits own interview answers" on public.interview_answers
  for update to authenticated
  using (private.is_doctor_of_clinic(clinic_id))
  with check (private.is_doctor_of_clinic(clinic_id) and answered_by = (select auth.uid()));
create policy "doctor deletes own interview answers" on public.interview_answers
  for delete to authenticated
  using (private.is_doctor_of_clinic(clinic_id));

create policy "doctor manages own gray cards" on public.gray_cards
  for all to authenticated
  using (private.is_doctor_of_clinic(clinic_id))
  with check (private.is_doctor_of_clinic(clinic_id));

create policy "doctor reads own clinic quizzes" on public.clinic_quizzes
  for select to authenticated
  using (private.is_doctor_of_clinic(clinic_id));

create policy "doctor reads own clinic questions" on public.clinic_questions
  for select to authenticated
  using (private.is_doctor_of_clinic_quiz(clinic_quiz_id));

create policy "doctor reads own VAs' unlocks" on public.unlocks
  for select to authenticated
  using (private.is_doctor_of_clinic_quiz(clinic_quiz_id));

create policy "doctor reads own VAs' attempts" on public.attempts
  for select to authenticated
  using (private.is_doctor_of_clinic_quiz(clinic_quiz_id));

create policy "doctor reads own VAs' proof uploads" on public.proof_uploads
  for select to authenticated
  using (private.is_doctor_of_clinic_quiz(clinic_quiz_id));

create policy "doctor reads own clinic reports" on public.notifications
  for select to authenticated
  using (exists (
    select 1 from public.attempts a
    where a.id = attempt_id and private.is_doctor_of_clinic_quiz(a.clinic_quiz_id)
  ));

-- ---------------------------------------------------------------------------
-- VA: own rows only. No direct access to clinic_questions or question_templates.
-- Unlocks and attempts are written by the server (service role), never the VA.
-- ---------------------------------------------------------------------------

create policy "va reads own unlocks" on public.unlocks
  for select to authenticated
  using (va_id = (select auth.uid()) and (select private.my_role()) = 'va');

-- The quiz shells (title, version, status) a VA has been assigned.
create policy "va reads assigned clinic quizzes" on public.clinic_quizzes
  for select to authenticated
  using (private.va_has_unlock(id));

-- Scores and AI feedback stay hidden until VFDA releases them.
create policy "va reads own released attempts" on public.attempts
  for select to authenticated
  using (
    va_id = (select auth.uid())
    and (select private.my_role()) = 'va'
    and feedback_released_at is not null
  );

create policy "va reads own proof uploads" on public.proof_uploads
  for select to authenticated
  using (va_id = (select auth.uid()) and (select private.my_role()) = 'va');

create policy "va adds own proof uploads" on public.proof_uploads
  for insert to authenticated
  with check (
    va_id = (select auth.uid())
    and (select private.my_role()) = 'va'
    and status = 'pending'
    and review_note is null
    and exists (
      select 1 from public.unlocks u
      where u.va_id = (select auth.uid())
        and u.clinic_quiz_id = proof_uploads.clinic_quiz_id
        and u.status <> 'locked'
    )
  );

-- ---------------------------------------------------------------------------
-- The only way a VA can read quiz items. Returns display columns only
-- (never answer, look_for or critical_fail), and only for a quiz that is
-- approved by VFDA and open for this VA right now.
-- ---------------------------------------------------------------------------

create or replace function public.get_open_quiz_items(p_clinic_quiz_id uuid)
returns table (
  id            uuid,
  "position"    integer,
  part          text,
  part_title    text,
  code          text,
  type          text,
  points        smallint,
  answer_format text,
  stem          text,
  options       jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1
    from public.unlocks u
    join public.clinic_quizzes q on q.id = u.clinic_quiz_id
    where u.clinic_quiz_id = p_clinic_quiz_id
      and u.va_id = (select auth.uid())
      and u.status = 'open'
      and q.status = 'approved'
      and private.my_role() = 'va'
  ) then
    raise exception 'This quiz is not open for you.' using errcode = '42501';
  end if;

  return query
    select c.id, c.position, c.part, c.part_title, c.code, c.type,
           c.points, c.answer_format, c.stem, c.options
    from public.clinic_questions c
    where c.clinic_quiz_id = p_clinic_quiz_id
    order by c.position, c.code;
end;
$$;

revoke all on function public.get_open_quiz_items(uuid) from public, anon;
grant execute on function public.get_open_quiz_items(uuid) to authenticated;

commit;
